import React from 'react';
import BookingForm from './component/BookingForm';

function App() {
  const slot = { id: 1, slotNumber: 'A1', hourlyRate: 5 };

  const handleBooked = () => {
    alert('Booking successful!');
  };

  return (
    <div className="App">
      <h1>Parking Slot Booking</h1>
      <BookingForm slot={slot} onBooked={handleBooked} />
    </div>
  );
}

export default App;
